mapper.select:
/* UserAuthMapper.selectUserAuthList 조회 조건에 맞는 사용자 목록을 사용자ID 순으로 조회 */ SELECT USR_ID, COALESCE(USR_NM, '') AS USR_NM, COALESCE(EMP_NO, '') AS EMP_NO, COALESCE(DEPT_CD, '') AS DEPT_CD, COALESCE(EML_ADDR, '') AS EML_ADDR, COALESCE(MOBL_NO, '') AS MOBL_NO, COALESCE(USR_STAT_CD, '') AS USR_STAT_CD, COALESCE(USR_LOCK_YN, 'N') AS USR_LOCK_YN, COALESCE(USR_CLS_CD, '') AS USR_CLS_CD, COALESCE(ECOM_DT, '') AS ECOM_DT, COALESCE(RESI_DT, '') AS RESI_DT, COALESCE(USE_ST_DT, '') AS ST_DT, COALESCE(USE_END_DT, '') AS END_DT, USE_YN FROM TB_USR_M
AND UPPER(USR_ID) LIKE '%' || UPPER(TRIM(#{usrId})) || '%'
AND USR_NM LIKE '%' || TRIM(#{usrNm}) || '%'
AND USR_CLS_CD = #{usrClsCd}
AND USE_YN = #{useYn}
ORDER BY USR_ID

mapper.delete:
/* UserAuthMapper.deleteUser 사용자를 삭제 */
DELETE FROM TB_USR_M
 WHERE USR_ID = #{usrId}

/* UserAuthMapper.deleteUserAuthGroupList 사용자의 권한그룹 매핑을 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_USR_AUTH_GRP_R
 WHERE USR_ID = #{usrId}

/* UserAuthMapper.deleteUserFavoriteList 사용자의 즐겨찾기를 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_PRGM_FAV_L
 WHERE USR_ID = #{usrId}

mapper.select:
/* UserAuthMapper.selectUserMenuAuthList 사용자의 화면 권한 목록을 메뉴ID 순으로 조회 */
SELECT USR_ID, MENU_ID, PRGM_ID
FROM TB_USR_MENU_R
WHERE USR_ID = #{usrId}
ORDER BY MENU_ID, PRGM_ID

mapper.insert:
/* UserAuthMapper.insertUserMenuAuth 사용자 화면 권한을 등록 (이미 있으면 건너뜀) */
INSERT INTO TB_USR_MENU_R (
    USR_ID, MENU_ID, PRGM_ID,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.usrId}, #{item.menuId}, #{item.prgmId},
    #{regrId}, CURRENT_TIMESTAMP, #{regrId}, CURRENT_TIMESTAMP
)
ON CONFLICT (USR_ID, MENU_ID, PRGM_ID) DO NOTHING

mapper.delete:
/* UserAuthMapper.deleteUserMenuAuth 사용자 화면 권한을 삭제 */
DELETE FROM TB_USR_MENU_R
 WHERE USR_ID  = #{usrId}
   AND MENU_ID = #{menuId}
   AND PRGM_ID = #{prgmId}

/* UserAuthMapper.deleteUserMenuAuthList 사용자의 화면 권한을 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_USR_MENU_R
 WHERE USR_ID = #{usrId}

mapper.select:
/* UserAuthMapper.selectUserComponentAuthList 사용자의 컴포넌트 권한을 조회 (프로그램ID가 없으면 전체) */
SELECT USR_ID, PRGM_ID, CMPN_ID, AUTH_YN
FROM TB_USR_CMPN_R
WHERE USR_ID = #{usrId}

  AND PRGM_ID = #{prgmId}

ORDER BY PRGM_ID, CMPN_ID

mapper.delete:
/* UserAuthMapper.deleteUserComponentAuthList 사용자의 컴포넌트 권한을 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_USR_CMPN_R
 WHERE USR_ID = #{usrId}

/* UserAuthMapper.deleteUserComponentAuthWithoutMenu 화면 권한이 남아 있지 않은 프로그램의 컴포넌트 권한을 삭제 */
DELETE FROM TB_USR_CMPN_R C
 WHERE C.USR_ID = #{usrId}
   AND NOT EXISTS (
        SELECT 1 FROM TB_USR_MENU_R M
         WHERE M.USR_ID  = C.USR_ID
           AND M.PRGM_ID = C.PRGM_ID
   )

/* UserAuthMapper.deleteUserAlarmList 사용자가 받은 알람을 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_ALRM_L
 WHERE RCVR_ID = #{usrId}

/* UserAuthMapper.deleteUserBatchAlarmReceiverList 사용자를 배치 알람수신자에서 모두 삭제 (사용자 삭제 시) */
DELETE FROM TB_DSPT_ALRM_RCVR_R
 WHERE USR_ID = #{usrId}
